import type { CSSProperties, HTMLAttributes, ReactNode } from 'react'

import { cx } from '~/lib/cx'
import styles from './layout.module.scss'

type Gap = 0 | 1 | 2 | 3 | 4 | 5 | 6 | 8 | 10
type Align = 'start' | 'center' | 'end' | 'stretch'
type Justify = 'start' | 'center' | 'end' | 'between'

const GAP: Record<Gap, string> = {
  0: styles.gap0,
  1: styles.gap1,
  2: styles.gap2,
  3: styles.gap3,
  4: styles.gap4,
  5: styles.gap5,
  6: styles.gap6,
  8: styles.gap8,
  10: styles.gap10,
}

const ALIGN: Record<Align, string> = {
  start: styles.alignStart,
  center: styles.alignCenter,
  end: styles.alignEnd,
  stretch: styles.alignStretch,
}

const JUSTIFY: Record<Justify, string> = {
  start: styles.justifyStart,
  center: styles.justifyCenter,
  end: styles.justifyEnd,
  between: styles.justifyBetween,
}

export interface StackProps extends HTMLAttributes<HTMLDivElement> {
  gap?: Gap
  align?: Align
  justify?: Justify
}

/** Vertical flex stack on the token spacing scale. */
export function Stack({
  gap = 3,
  align = 'stretch',
  justify = 'start',
  className,
  ...props
}: StackProps) {
  return (
    <div
      className={cx(styles.stack, GAP[gap], ALIGN[align], JUSTIFY[justify], className)}
      {...props}
    />
  )
}

export interface InlineProps extends HTMLAttributes<HTMLDivElement> {
  gap?: Gap
  align?: Align
  justify?: Justify
  wrap?: boolean
}

/** Horizontal flex row that wraps by default. */
export function Inline({
  gap = 2,
  align = 'center',
  justify = 'start',
  wrap = true,
  className,
  style,
  ...props
}: InlineProps) {
  return (
    <div
      className={cx(styles.inline, GAP[gap], ALIGN[align], JUSTIFY[justify], className)}
      style={wrap ? style : { flexWrap: 'nowrap', ...style }}
      {...props}
    />
  )
}

export interface GridProps extends HTMLAttributes<HTMLDivElement> {
  gap?: Gap
  /** Minimum column width before wrapping. */
  min?: string
  /** Fixed column count; omit for auto-fit columns. */
  columns?: number
}

/** Auto-fit CSS grid with a token gap and a minimum column width. */
export function Grid({
  gap = 4,
  min = '14rem',
  columns,
  className,
  style,
  ...props
}: GridProps) {
  return (
    <div
      className={cx(styles.grid, GAP[gap], className)}
      style={
        {
          '--layout-min': min,
          ...(columns
            ? { gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))` }
            : {}),
          ...style,
        } as CSSProperties
      }
      {...props}
    />
  )
}

export interface FlexProps extends HTMLAttributes<HTMLDivElement> {
  direction?: 'row' | 'column'
  wrap?: boolean
  inline?: boolean
  gap?: Gap
  align?: Align
  justify?: Justify
}

/** General flex container for one-off layouts. */
export function Flex({
  direction = 'row',
  wrap = false,
  inline = false,
  gap = 2,
  align = 'stretch',
  justify = 'start',
  className,
  ...props
}: FlexProps) {
  return (
    <div
      className={cx(
        inline ? styles.flexInline : styles.flex,
        direction === 'column' ? styles.flexColumn : styles.flexRow,
        wrap ? styles.flexWrap : styles.flexNowrap,
        GAP[gap],
        ALIGN[align],
        JUSTIFY[justify],
        className,
      )}
      {...props}
    />
  )
}

export interface SplitProps extends HTMLAttributes<HTMLDivElement> {
  /** Secondary pane. */
  side: ReactNode
  children: ReactNode
  sideWidth?: string
  sidePosition?: 'start' | 'end'
}

/** Two-pane layout that collapses to one column when its container is narrow. */
export function Split({
  side,
  children,
  sideWidth = '18rem',
  sidePosition = 'start',
  className,
  style,
  ...props
}: SplitProps) {
  return (
    <div
      className={cx(
        styles.split,
        sidePosition === 'end' && styles.splitEnd,
        className,
      )}
      style={{ '--split-size': sideWidth, ...style } as CSSProperties}
      {...props}
    >
      <div className={styles.splitSide}>{side}</div>
      <div className={styles.splitMain}>{children}</div>
    </div>
  )
}

export interface ContainerProps extends HTMLAttributes<HTMLDivElement> {
  size?: 'sm' | 'md' | 'lg' | 'xl' | 'full'
}

/** Centered page container with a max width. */
export function Container({ size = 'lg', className, ...props }: ContainerProps) {
  const sizes = {
    sm: styles.containerSm,
    md: styles.containerMd,
    lg: styles.containerLg,
    xl: styles.containerXl,
    full: styles.containerFull,
  }

  return <div className={cx(styles.container, sizes[size], className)} {...props} />
}

export interface PageSectionProps
  extends Omit<HTMLAttributes<HTMLElement>, 'title'> {
  title?: ReactNode
  description?: ReactNode
  actions?: ReactNode
  children: ReactNode
}

/** Page-level section with an optional heading, description and actions. */
export function PageSection({
  title,
  description,
  actions,
  children,
  className,
  ...props
}: PageSectionProps) {
  return (
    <section className={cx(styles.section, className)} {...props}>
      {title || description || actions ? (
        <div className={styles.sectionHead}>
          <div className={styles.sectionCopy}>
            {title ? <h2 className={styles.sectionTitle}>{title}</h2> : null}
            {description ? (
              <p className={styles.sectionDescription}>{description}</p>
            ) : null}
          </div>
          {actions ? <div className={styles.sectionActions}>{actions}</div> : null}
        </div>
      ) : null}
      {children}
    </section>
  )
}

@use 'styles' as vz;

.stack,
.inline {
  display: flex;
}

.stack {
  flex-direction: column;
}

.inline {
  flex-flow: row wrap;
}

.flex {
  display: flex;
}

.flex-inline {
  display: inline-flex;
}

.flex-column {
  flex-direction: column;
}

.flex-row {
  flex-direction: row;
}

.flex-nowrap {
  flex-wrap: nowrap;
}

.flex-wrap {
  flex-wrap: wrap;
}

.split {
  display: grid;
  grid-template-columns: minmax(0, var(--split-size, 18rem)) minmax(0, 1fr);
  gap: vz.space(4);
  align-items: start;
  container-type: inline-size;
}

.split-end {
  grid-template-columns: minmax(0, 1fr) minmax(0, var(--split-size, 18rem));
}

.split-end .split-side {
  order: 2;
}

.split-main {
  min-width: 0;
}

@container (max-width: 38rem) {
  .split,
  .split-end {
    grid-template-columns: minmax(0, 1fr);
  }

  .split-end .split-side {
    order: 0;
  }
}

.gap-0 {
  gap: 0;
}

.gap-1 {
  gap: vz.space(1);
}

.gap-2 {
  gap: vz.space(2);
}

.gap-3 {
  gap: vz.space(3);
}

.gap-4 {
  gap: vz.space(4);
}

.gap-5 {
  gap: vz.space(5);
}

.gap-6 {
  gap: vz.space(6);
}

.gap-8 {
  gap: vz.space(8);
}

.gap-10 {
  gap: vz.space(10);
}

.align-start {
  align-items: flex-start;
}

.align-center {
  align-items: center;
}

.align-end {
  align-items: flex-end;
}

.align-stretch {
  align-items: stretch;
}

.justify-start {
  justify-content: flex-start;
}

.justify-center {
  justify-content: center;
}

.justify-end {
  justify-content: flex-end;
}

.justify-between {
  justify-content: space-between;
}

.grid {
  display: grid;
  grid-template-columns: repeat(
    auto-fit,
    minmax(min(var(--layout-min, 14rem), 100%), 1fr)
  );
}

.container {
  width: 100%;
  margin-inline: auto;
  padding-inline: vz.space(4);
}

.container-sm {
  max-width: 40rem;
}

.container-md {
  max-width: 56rem;
}

.container-lg {
  max-width: 72rem;
}

.container-xl {
  max-width: 88rem;
}

.container-full {
  max-width: none;
}

.section {
  display: flex;
  flex-direction: column;
  gap: vz.space(4);
  padding-block: vz.space(6);
}

.section-head {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: vz.space(3);
}

.section-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: vz.space(1);
}

.section-title {
  margin: 0;
  font-size: vz.font-size('2xl');
  font-weight: 650;
  letter-spacing: -0.02em;
}

.section-description {
  margin: 0;
  max-width: 42rem;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('sm');
  line-height: 1.6;
}

.section-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: vz.space(2);
}

@include vz.down('sm') {
  .container {
    padding-inline: vz.space(3);
  }
}
